"""translation_tool/plugins/ftbquests/ftbquests_lmtranslator.py 璅∠????券????祆?獢?蝢拍????蝔?靘?獢隞芋蝯?怒?蝬剛風瘜冽?嚗瑼??撘?docstring ?冽蝬剛風隤芣?嚗?隞?”銵霈??"""# ftbquests_lmtranslator.py# ------------------------------------------------------------# FTB Quests (Already Extracted JSON) -> translate_batch_smart -> Export translated JSON maps# - DOES NOT run extractor# - Reads extracted .json files containing {key: text} pairs# - Outputs translated {key: text} JSON with same relative path structure# - If input file is like ru_ru.json (or other lang codes), output renamed to zh_tw.json# - total passed to smart = global total keys across all files# ------------------------------------------------------------from __future__ import annotationsfrom dataclasses import dataclassfrom pathlib import Pathfrom typing import Dict, Any, List, Optional, Tuplefrom concurrent.futures import ThreadPoolExecutor, as_completedimport mathfrom translation_tool.core.lm_translator_main import translate_batch_smartfrom translation_tool.core.lm_config_rules import validate_api_keysfrom translation_tool.utils.config_manager import load_configfrom translation_tool.core.lm_translator_shared import (    fast_split_items_by_cache,  # ???啣?嚗???瘚?    translate_items_with_cache_loop,    CacheRule,    TouchSet,  # ???啣?嚗ouched/flush    TranslationRecorder,  # ???啣?嚗蕃霅航???    write_dry_run_preview,  # ???啣?嚗ry-run preview 瑼?    write_cache_hit_preview,  # ???啣?嚗ache hit preview 瑼?    _is_valid_hit,  # ???啣?嚗ache hit ?斗    _get_default_batch_size,)from translation_tool.plugins.shared.json_io import (    read_json_dict,    write_json_dict,    collect_json_files,)from translation_tool.plugins.shared.lang_path_rules import (    compute_output_path,)from translation_tool.plugins.shared.lang_text_rules import is_already_zhfrom translation_tool.plugins.shared.rich_text_shield import shield_text, unshield_textfrom translation_tool.utils.log_unit import (    log_info,    log_error,)# -------------------------# Smart 蝧餉陌頧?剁?鞈??澆?頧?嚗?# -------------------------def map_to_items(    mapping: Dict[str, Any],    cache_type: str,    file_hint: str,) -> List[Dict[str, Any]]:    """    撠?{key: text} ??憪???頧???translate_batch_smart ?航??? item ?澆???    瘥???item 隞?”??璇蝧餉陌?????◤?莎?    - cache 瘥?    - batch 蝧餉陌    - 蝧餉陌蝯??神    ??閬身閮???    - smart 蝧餉陌?冽??? item["file"] ?斗鞈?憿?    - FTB Quests ??瑟?隞嗆嚗楝敺葉敹?? "/ftbquests/"    - ?迨 file_hint??摰?????"/ftbquests/"    - ??銝? "/lang/"嚗??鋡怨炊?斤 Minecraft Lang 蝧餉陌    ???舐隞暻?file_hint 銝撖阡?瑼?頝臬?嚗??????內頝臬???    """    items: List[Dict[str, Any]] = []    for k, v in mapping.items():        # key 敹??臬?銝莎?隤? key嚗?        if not isinstance(k, str):            continue        # value 敹??舫?蝛箇摮葡嚗祕??蝧餉陌?摰對?        if not isinstance(v, str) or not v.strip():            continue        items.append(            {                # ?? smart translator ?斗?函?瑼??內頝臬?                # ?? 敹?? "/ftbquests/"                "file": file_hint,                # 隤? key嚗?憒?quest.xxx.title嚗?                "path": k,                # ????嚗翰??瘥??剁?                "source_text": v,                # ?嗅???嚗?鋡怎蕃霅臬閬神嚗?                "text": v,                # ??敹怠???嚗???cache_rules嚗?                "cache_type": cache_type,  # 靘? "ftbquests"            }        )    return itemsdef count_translatable_keys(mapping: Dict[str, Any]) -> int:    """    閮? mapping 銝准祕?蝧餉陌??銝脫??    ?斗璇辣嚗?    - value 敹??臬?銝?    - ?駁蝛箇敺??摰?    ????其?嚗?    - 憿舐內?脣漲    - 閮? cache hit / miss    - 雿 batch 蝧餉陌?蜇?皞?    """    return sum(1 for _, v in mapping.items() if isinstance(v, str) and v.strip())@dataclassclass DryRunStats:    """    Dry-run嚗岫頝?璅∪?銝?蝯梯?鞈?蝯???    ?券?    - UI 憿舐內    - ?汗蝧餉陌閬芋    - 蝣箄? cache ?賭葉瘥??臬??    """    files: int = 0  # ????獢    total_keys: int = 0  # 蝮賢?銝脫    cache_hit: int = 0  # 敹怠??賭葉??    cache_miss: int = 0  # 撖阡??蝧餉陌??    per_file: list[dict] = None  # 瘥?獢??敦# -------------------------# Public API (callable from pipeline)# -------------------------def translate_ftb_pending_to_zh_tw(    *,    input_lang_dir: str | Path,    output_lang_dir: str | Path,    session=None,    rename_langs: Optional[set[str]] = None,    dry_run: bool = False,  # ???啣?    write_new_cache: bool = True,  # ???啣?) -> dict:    """    撠策 UI/???澆嚗?    - input_lang_dir: 靘? <output_dir>/敺蕃霅?config/ftbquests/quests/lang                      嚗釣??閬??lang ?惜嚗??詨?頝臬???en_us/ ??踵???zh_tw嚗?    - output_lang_dir: 靘? <output_dir>/config/ftbquests/quests/lang                       嚗撓?箸??芸???en_us 鞈?憭暹?? zh_tw嚗?    - session: ?舫嚗靘?add_log / set_progress    """    validate_api_keys()    in_dir = Path(input_lang_dir).resolve()    out_dir = Path(output_lang_dir).resolve()    out_dir.mkdir(parents=True, exist_ok=True)    def set_prog(v: float):        """閮剖?蝧餉陌?脣漲??""        if session is not None and hasattr(session, "set_progress"):            try:                session.set_progress(v)            except Exception:                pass    # rename langs ?身瘝輻雿?CLI ???殷?雿?pending ?虜?芣? en_us嚗?憭芣??典嚗?    if rename_langs is None:        rename_langs = {            "ru_ru",            "ja_jp",            "ko_kr",            "zh_cn",            "zh_hk",            "zh_sg",            "pt_br",            "es_es",            "en_us",            "fr_fr",            "de_de",            "it_it",            "pl_pl",            "tr_tr",            "uk_ua",            "cs_cz",            "hu_hu",            "nl_nl",            "sv_se",            "no_no",            "da_dk",            "fi_fi",        }    if not in_dir.exists() or not in_dir.is_dir():        raise FileNotFoundError(f"input_lang_dir 銝??冽?銝鞈?憭橘?{in_dir}")    json_files = collect_json_files(in_dir)    if not json_files:        raise FileNotFoundError(f"?曆??唬遙雿?.json嚗in_dir}")    # ---- Global total keys (raw) + cache mappings ----    per_file_counts: List[Tuple[Path, int]] = []    global_total_keys = 0    # ??Issue #7 靽桀儔嚗楨摮?JSON mapping ?踹???霈??    src_mapping_cache: Dict[Path, Dict[str, Any]] = {}    def _count_one(src: Path) -> Tuple[Path, int, Dict[str, Any]]:        """霈??JSON 銝衣絞閮蝧餉陌?萄潭????敹怠? mapping??""        try:            mapping = read_json_dict(src)            c = count_translatable_keys(mapping)            return src, int(c), mapping        except Exception:            return src, 0, {}    # max_workers 雿隞交??config ??parallel_execution_workers    max_workers = (        load_config().get("translator", {}).get("parallel_execution_workers", 4)    )    with ThreadPoolExecutor(max_workers=max_workers) as ex:        futs = [ex.submit(_count_one, src) for src in json_files]        for fu in as_completed(futs):            src, c, mapping = fu.result()            per_file_counts.append((src, c))            global_total_keys += c            if mapping:  # ???芰楨摮?蝛箇? mapping                src_mapping_cache[src] = mapping    # 靽?蝛拙???嚗???瑁?蝺??湔?摨?嚗?    per_file_counts.sort(key=lambda x: x[0].as_posix())    if global_total_keys == 0:        log_info("?對? [FTB-LM] 0 keys嚗歲?蕃霅?)        return {"written_files": 0, "total_keys": 0, "out_dir": str(out_dir)}    # ---- Cache rules ----    cache_rules = {"ftbquests": CacheRule("path|source_text")}    # ????閮??祕??蝧餉陌?蜇???典? miss嚗?    global_total_to_translate = 0    global_total_hit = 0    for src, key_count in per_file_counts:        if key_count == 0:            continue        try:            # ??Issue #7 靽桀儔嚗?乩蝙?函楨摮? mapping嚗???銴???            mapping = src_mapping_cache.get(src, {})            if not mapping:                continue            rel_src = src.relative_to(in_dir).as_posix()            file_hint = f"config/ftbquests/quests/{rel_src}"            all_items = map_to_items(                mapping, cache_type="ftbquests", file_hint=file_hint            )            cached_items, items_to_translate = fast_split_items_by_cache(                all_items,                cache_rules=cache_rules,                is_valid_hit=_is_valid_hit,            )            # ??銝剜?/撌脩蕃霅荔?銝?LM嚗?銝? cache_miss            already_zh_items = []            real_to_translate = []            for it in items_to_translate:                s = str(it.get("source_text") or it.get("text") or "")                if is_already_zh(s):                    already_zh_items.append(it)                else:                    real_to_translate.append(it)            global_total_hit += len(cached_items)            global_total_to_translate += len(real_to_translate)        except Exception:            pass    log_info(        f"\n?? [FTB-LM][??摰] ?潛敺???獢?{len(json_files)} ??| ?蝮賣??殷?{global_total_keys} 璇?        f"\n??[FTB-LM][?脣漲??] 撌脣?敹怠?頛嚗global_total_hit} 璇?| ?拚?? AI 蝧餉陌嚗global_total_to_translate} 璇?    )    if global_total_to_translate == 0:        log_info(            "?對? [FTB-LM][?? ?剖?嚗??摰寧??賭葉敹怠?嚗?隤輻 AI嚗??湔撠瑼???        )    if global_total_to_translate == 0:        set_prog(0.99)  # ?踹??祇?頝?1.0嚗? UI ???典撠???閬死??    # ---- Translate per file (shared loop + cache) ----    translated_done = 0  # ???芰? API 蝧餉陌摰?嚗蜓?脣漲??嚗?    cache_hit_done_so_far = 0  # ??撌脣神?亥撓?箇? cache hit嚗擃??嚗?    total_written = 0    # ---- Dry-run stats container ----    per_file_rows: list[dict] = []    # ---- Dry-run: 銝蕃霅胯?頛詨 ----    dry_preview_items: List[Dict[str, Any]] = []    all_cached_items: list[dict] = []    rec = TranslationRecorder()    touch = TouchSet()    # touched_files 撠???writer嚗?撠??嚗?瑼??銝??dst/out_map嚗?    _file_write_table: dict[str, tuple[Path, Dict[str, str]]] = {}    def _writer(file_id: str) -> None:        """撖怠蝧餉陌蝯??唳?獢?""        dst_path, data = _file_write_table[file_id]        write_json_dict(dst_path, data)    for idx, (src, key_count) in enumerate(per_file_counts, start=1):        if key_count == 0:            continue        # ??Issue #7 靽桀儔嚗?乩蝙?函楨摮? mapping嚗???銴???        mapping = src_mapping_cache.get(src, {})        if not mapping:            log_error(f"?? [FTB-LM] ?曆??啣翰?? mapping嚗src}")            continue        rel_src = src.relative_to(in_dir).as_posix()  # e.g. en_us/ftb_lang.json        file_hint = (            f"config/ftbquests/quests/{rel_src}"  # ??include /ftbquests/ and no /lang/        )        all_items = map_to_items(mapping, cache_type="ftbquests", file_hint=file_hint)        cached_items, items_to_translate = fast_split_items_by_cache(            all_items,            cache_rules=cache_rules,            is_valid_hit=_is_valid_hit,        )        already_zh_items = []        real_to_translate = []        for it in items_to_translate:            s = str(it.get("source_text") or it.get("text") or "")            if is_already_zh(s):                already_zh_items.append(it)            else:                real_to_translate.append(it)        items_to_translate = real_to_translate  # ??閬?????蝧餉陌??        hit = len(cached_items)        miss = len(items_to_translate)        already_zh = len(already_zh_items)        if hit > 0:            sample = cached_items[0]            log_info(f"?? [FTB-LM] 敹怠??賭葉蝭?嚗sample.get('path')}")        if miss > 0:            sample = items_to_translate[0]            log_info(f"?? [FTB-LM] 敺蕃霅舐?靘?{sample.get('path')}")        dst = compute_output_path(src, in_dir, out_dir, rename_langs)        log_info(            f"?? [FTB-LM][瑼? {idx}/{len(per_file_counts)}] 甇???嚗rel_src}\n"            f"?? ?祆??敦嚗蜇璇 {key_count} | 頛敹怠? {hit} | 撌脣銝剜?(頝喲?) {already_zh} | ?蝧餉陌 {miss}\n"            f"? 頛詨頝臬?嚗dst.relative_to(out_dir).as_posix()}"        )        per_file_rows.append(            {                "file": rel_src,                "keys": key_count,                "cache_hit": hit,                "cache_miss": miss,                "dst": dst.relative_to(out_dir).as_posix(),            }        )        # ---- Dry-run: 銝蕃霅胯?頛詨 ----        if dry_run:            # ???園? preview 璅?嚗??憭改??憭?2000嚗?            if len(dry_preview_items) < 2000:                dry_preview_items.extend(                    items_to_translate[: 2000 - len(dry_preview_items)]                )                # ??NEW嚗??cache hit嚗??憭改??憭?2000嚗?芾?隤踵嚗?            if len(all_cached_items) < 2000:                all_cached_items.extend(cached_items[: 2000 - len(all_cached_items)])            # 隞交?獢?誨蝧餉陌??脣漲??嚗?蕃霅舫???銝???閬死頝唾?            set_prog(min(idx / len(per_file_counts), 1.0))            log_info(                f"?妒 [皜祈岫璅∪?] ?脣漲嚗idx}/{len(per_file_counts)}\n"                f"?砍?頛詨嚗rel_src} ??{dst.relative_to(out_dir).as_posix()}\n"                f"?摯?敦嚗蜇璇 {key_count} | 敹怠??賭葉 {hit} | ?蝧餉陌 {miss} | ?摯?寞活 {math.ceil(miss / _get_default_batch_size('ftbquests', None)) if _get_default_batch_size('ftbquests', None) > 0 else 'N/A'}\n"                f"蝝航??摯?脣漲嚗translated_done} / {global_total_to_translate}"            )            continue        # ============================        # ???迤蝧餉陌嚗? dry-run嚗?        # ============================        # out_map嚗??典??摨??踹?銝剜?撓?箇撩 key嚗?        out_map: Dict[str, str] = {            k: v            for k, v in mapping.items()            if isinstance(k, str) and isinstance(v, str)        }        # cache hits 閬?        for it in cached_items:            p = it.get("path")            t = it.get("text")            if isinstance(p, str) and isinstance(t, str):                out_map[p] = t                try:                    rec.record(                        cache_type="ftbquests",                        file_id=rel_src,                        path=p,                        src=str(it.get("source_text") or ""),                        dst=t,                        cache_hit=True,                        extra={"dst_file": dst.relative_to(out_dir).as_posix()},                    )                except Exception:                    pass        # ?典銝?cache嚗?亥撓??        if not items_to_translate:            # write_json_dict(dst, out_map)            file_id = dst.as_posix()            _file_write_table[file_id] = (dst, out_map)            touch.touch(file_id)            touch.flush(_writer)  # ?撠??蝑?雿?冽?甈⊿撖恬?雿粥???恣蝺?            total_written += 1            # ????獢? cache hit 撌脩??迤撖恍脰撓?綽??湧?摰?閬?            cache_hit_done_so_far += hit            # ??銝駁脣漲銝?嚗ranslated_done 銝?嚗?            set_prog(min(translated_done / max(global_total_to_translate, 1), 1.0))            overall_done = cache_hit_done_so_far + translated_done            progress_pct = (                (overall_done / global_total_keys * 100) if global_total_keys > 0 else 0            )            log_info(                f"??[敹怠?頝喲?] 瑼? {idx}/{len(per_file_counts)}嚗rel_src}\n"                f"? 撠頝臬?嚗dst.relative_to(out_dir).as_posix()}\n"                f"?? ??蝯?嚗銝剖翰??{hit} 璇?| API 隤輻 0 璇n"                f"? ?典?摰?摨佗?{overall_done} / {global_total_keys} ({progress_pct:.1f}%)"            )            continue        # ??Issue #8 靽桀儔嚗? callbacks 摰儔?刻艘???剁??寧撌亙??賢?        def _fmt_eta(sec: float) -> str:            """?澆??擗???""            if sec <= 0:                return ""            m, s = divmod(int(sec), 60)            if m > 0:                return f"{m}m{s:02d}s"            return f"{s}s"        def make_on_progress(set_prog, _fmt_eta):            def on_progress(p: float, msg: str, eta_sec: float) -> None:                """?勗?蝧餉陌?脣漲??""                eta_txt = _fmt_eta(eta_sec)                if eta_txt:                    log_info(f"??[AI 蝧餉陌銝苗 {msg} | ?摯?拚???嚗eta_txt}")                else:                    log_info(f"?? [AI 蝧餉陌銝苗 {msg}")                set_prog(p)            return on_progress        def make_on_translated_item(rel_src, dst, out_map, rec, out_dir):            def on_translated_item(it: Dict[str, Any]) -> None:                """??蝧餉陌蝯?銝血神?交?撠?""                p = it.get("path")                t = it.get("text")                src_text = str(it.get("source_text") or "")                if isinstance(p, str) and isinstance(t, str):                    try:                        shielded_src = shield_text(src_text)                        t = unshield_text(t, shielded_src.shields)                    except Exception:                        pass                    out_map[p] = t                    try:                        rec.record(                            cache_type="ftbquests",                            file_id=rel_src,                            path=p,                            src=src_text,                            dst=t,                            cache_hit=False,                            extra={"dst_file": dst.relative_to(out_dir).as_posix()},                        )                    except Exception:                        pass            return on_translated_item        def make_on_batch_flushed(file_id, touch, _writer, dst, out_map):            def on_batch_flushed() -> None:                """?寥?撖怠蝧餉陌蝯???""                try:                    touch.touch(file_id)                    touch.flush(_writer)  # ?撠??瘥銋璅?神嚗?葉?瑟?憭?                except Exception:                    # fallback                    write_json_dict(dst, out_map)            return on_batch_flushed        # ??蝣箔?甇斗?獢蝧餉陌頝臬?銋? file_id        file_id = dst.as_posix()        _file_write_table[file_id] = (dst, out_map)        # ??Issue #8 靽桀儔嚗蝙?典極撱撘撱?callbacks        on_translated_item = make_on_translated_item(rel_src, dst, out_map, rec, out_dir)        on_batch_flushed = make_on_batch_flushed(file_id, touch, _writer, dst, out_map)        on_progress = make_on_progress(set_prog, _fmt_eta)        res = translate_items_with_cache_loop(            items_to_translate,            total_for_smart=global_total_to_translate,            translate_batch_smart=lambda batch, total: translate_batch_smart(                batch, total=total            ),            write_new_cache=bool(write_new_cache),  # ???寞?????            cache_rules=cache_rules,            on_translated_item=on_translated_item,            on_batch_flushed=on_batch_flushed,            on_progress=on_progress,        )        # final write        touch.touch(file_id)        touch.flush(_writer)        total_written += 1        # ??獢? cache hit 銋歇撖怠頛詨        cache_hit_done_so_far += hit        # ?芣? API 撖阡?蝧餉陌?賊??脖蜓?脣漲        translated_done += int(res.processed or 0)        set_prog(min(translated_done / max(global_total_to_translate, 1), 1.0))        overall_done = cache_hit_done_so_far + translated_done        progress_pct = (            (overall_done / global_total_keys * 100) if global_total_keys > 0 else 0        )        log_info(            f"??[瑼?摰?] {rel_src} 撌脣神?功n"            f"?? 蝧餉陌?豢?嚗甈∠蕃霅?{int(res.processed or 0)} 璇?| 瑼????{res.status}\n"            f"? ?典??脣漲嚗?歇摰? {overall_done} / {global_total_keys} ({progress_pct:.1f}%)"        )        if res.status == "ALL_KEYS_EXHAUSTED":            log_info("?? [FTB-LM] ALL_KEYS_EXHAUSTED嚗歇頛詨?桀???嚗?甇Ｕ?)            break    # ---- Dry-run 蝯偏?? ----    if dry_run:        batch_size = _get_default_batch_size("ftbquests", None)        est_batches = (            math.ceil(global_total_to_translate / batch_size)            if isinstance(global_total_to_translate, int) and batch_size > 0            else None        )        meta = {            "files": len(per_file_rows),            "total_keys": global_total_keys,            "cache_hit": global_total_hit,            "cache_miss": global_total_to_translate,            "estimated_batches": est_batches,        }        try:            # ?嚗?蝧餉陌 preview            write_dry_run_preview(                out_dir,                dry_preview_items,                meta=meta,                filename="_ftbquests_dry_run_preview.json",  # ?舫嚗?蝣箸???            )            # ??NEW嚗ache hit preview            write_cache_hit_preview(                out_dir,                all_cached_items,                filename="_ftbquests_dry_run_cache_hit_preview.json",                meta=meta,            )        except Exception as e:            log_error(f"?? [FTB-LM] DRY-RUN preview 頛詨憭望?嚗e}")        return {            "dry_run": True,            "files": len(per_file_rows),            "total_keys": global_total_keys,            "cache_hit": global_total_hit,            "cache_miss": global_total_to_translate,            "estimated_batches": est_batches,            "out_dir": str(out_dir),            "per_file": per_file_rows,        }    try:        rec.export_json(out_dir / "translation_map.json")        rec.export_csv(out_dir / "translation_map.csv")        log_info(f"??[FTB-LM] 撌脣??translation_map.json / .csv ??{out_dir}")    except Exception:        log_error("?? [FTB-LM] ?臬 translation_map 憭望?")        pass    log_info(f"??[隞餃?蝧餉陌摰?] 撌脣? {total_written} ?蕃霅舀?獢撓?箄嚗out_dir}")    log_info("?? ?內嚗?臭誑?刻府?桅?銝??translation_map.csv 靘撠蕃霅舀??桃敦蝭??)    batch_size = _get_default_batch_size("ftbquests", None)    est_batches = (        math.ceil(global_total_to_translate / batch_size)        if isinstance(global_total_to_translate, int) and batch_size > 0        else None    )    return {        "dry_run": False,        "written_files": total_written,        "total_keys": global_total_keys,        "cache_hit": global_total_hit,        "cache_miss": global_total_to_translate,        "estimated_batches": est_batches,        "out_dir": str(out_dir),    }